content.text:
{
  "name": "串口仪器通信基类组件",
  "name_en": "Serial Instrument Communication Base Component",
  "manufacturer": "",
  "description": "非物理实验软件组件，用于实验自动化中通过 pyserial 管理串口连接、收发原始字节数据并检查端口状态，作为各类串口仪器驱动的通用基础类。",
  "description_en": "A non-physical laboratory software component used in automation to manage serial connections via pyserial, send and receive raw byte data, and check port status. It serves as a common base class for serial instrument drivers.",
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "打开串口连接。",
      "description_en": "Open the serial port connection."
    },
    {
      "action_name": "auto-finalize",
      "description": "关闭串口连接。",
      "description_en": "Close the serial port connection."
    },
    {
      "action_name": "auto-is_open",
      "description": "检查串口是否已打开。",
      "description_en": "Check whether the serial port is open."
    },
    {
      "action_name": "auto-raw_send",
      "description": "通过串口发送原始字节数据。",
      "description_en": "Send raw byte data through the serial port."
    },
    {
      "action_name": "auto-raw_recv",
      "description": "通过串口接收指定长度的原始字节数据。",
      "description_en": "Receive raw byte data of a specified length through the serial port."
    }
  ],
  "tag_hints": [
    "serial communication",
    "pyserial",
    "instrument control base class",
    "raw byte transfer",
    "port open/close",
    "lab automation software"
  ]
}

